using System.IO;using System.Reflection;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace DanceStudio;
public static class LayoutTests {
 static object Field(object obj,string name)=>obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(obj)!;
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);++i)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i)))yield return child;}
 public static void Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);string oldPath=UiText.SettingsPath,oldLanguage=UiText.Language;UiText.SettingsPath=Path.Combine(folder,"language.json");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var reports=new List<object>();int checks=0;MainWindow? current=null;Exception? error=null;
 void Check(bool value,string description){checks++;if(!value)throw new Exception(description);}
 async Task Inspect(MainWindow w,string key){await Task.Delay(160);w.UpdateLayout();var root=(Grid)w.Content;var toolbar=Walk(root).OfType<Grid>().Single(g=>g.Name=="EditorToolbar");var workspace=Walk(root).OfType<Grid>().Single(g=>g.Name=="EditorWorkspace");var title=(TextBox)Field(w,"title");var tabs=(TabControl)Field(w,"timelineTabs");var status=(TextBlock)Field(w,"status");
  Rect Bounds(FrameworkElement f,Visual parent)=>new(f.TransformToAncestor(parent).Transform(new Point()),f.RenderSize);
  bool Inside(Rect a,Size size)=>a.Left>=-.5&&a.Top>=-.5&&a.Right<=size.Width+.5&&a.Bottom<=size.Height+.5;
  Check(!Walk(toolbar).OfType<TextBlock>().Any(t=>t.Text is "Project name" or "프로젝트 이름"),"no visible project-name caption");Check(toolbar.ActualHeight<=80,"toolbar and name input fit one row at tested width "+key);
  Check(w.Content is Grid,"shell is a bounded Grid, not a whole-window ScrollViewer");Check(!Walk(toolbar).OfType<Button>().Any(b=>b.Content as string==UiText.T("t0138")),"editor-export toolbar button removed");Check(Inside(Bounds(toolbar,root),root.RenderSize)&&Inside(Bounds(workspace,root),root.RenderSize)&&Inside(Bounds(status,root),root.RenderSize),"toolbar, workspace and status fit root "+key);
  Check(Inside(Bounds(title,toolbar),toolbar.RenderSize)&&title.ActualWidth>=100,"title field remains fully within toolbar "+key);Check(title.TransformToAncestor(toolbar).Transform(new Point()).Y<toolbar.ActualHeight,"title is in toolbar");
  var preview=Walk(workspace).OfType<Grid>().Single(g=>g.Name=="PreviewAndSettings");Check(Inside(Bounds(preview,workspace),workspace.RenderSize)&&Inside(Bounds(tabs,workspace),workspace.RenderSize),"preview and timeline fit workspace "+key);Check(preview.ActualHeight>=120&&tabs.ActualHeight>=278,"preview/timeline retain usable space "+key);
  var basic=(TimelineView)Field(w,"timeline");if(tabs.SelectedIndex==0)Check(Inside(Bounds(basic,tabs),tabs.RenderSize),"basic timeline has no clipped footer "+key);
  foreach(var group in Walk(toolbar).OfType<Border>().Where(b=>b.Child is WrapPanel)){Check(Inside(Bounds(group,toolbar),toolbar.RenderSize),"toolbar group stays within bounded header "+key);}
  var titleCard=Walk(toolbar).OfType<Border>().Single(b=>b.Name=="ProjectTitleCard");var left=toolbar.Children.OfType<WrapPanel>().Single();Check(Bounds(left,toolbar).Right<=Bounds(titleCard,toolbar).Left+.5,"toolbar controls do not overlap project name "+key);
  var bmp=new RenderTargetBitmap((int)Math.Ceiling(w.ActualWidth),(int)Math.Ceiling(w.ActualHeight),96,96,PixelFormats.Pbgra32);bmp.Render(w);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var stream=File.Create(Path.Combine(folder,key+".png")))png.Save(stream);reports.Add(new{key,width=w.ActualWidth,height=w.ActualHeight,root=root.RenderSize.ToString(),toolbar=toolbar.RenderSize.ToString(),preview=preview.RenderSize.ToString(),timeline=tabs.RenderSize.ToString(),titleWidth=title.ActualWidth,dpi=VisualTreeHelper.GetDpi(w).DpiScaleX});
 }
 app.Startup+=async(_,_)=>{try{foreach(string language in new[]{"ko","en"}){UiText.SetLanguage(language);current=new MainWindow{ShowInTaskbar=false};current.Show();await current.LoadProject(new SongProject{Title="Layout project",ExportOut=120});var title=(TextBox)Field(current,"title");title.Text="Project name roundtrip · 프로젝트 이름";Check(current.Project.Title==title.Text,"toolbar title updates existing project title");string project=Path.Combine(folder,"title-"+language+".danceproj");current.Project.Save(project);Check(SongProject.Load(project).Title==title.Text,"toolbar title survives project save/reopen");title.Text="Intergalactia";
  current.Width=1440;current.Height=960;await Inspect(current,language+"-1440-base");var tabs=(TabControl)Field(current,"timelineTabs");tabs.SelectedIndex=1;await Inspect(current,language+"-1440-facial");current.Width=1120;current.Height=780;await Inspect(current,language+"-1120-facial");tabs.SelectedIndex=0;await Inspect(current,language+"-1120-base");current.WindowState=WindowState.Maximized;await Inspect(current,language+"-maximized");current.WindowState=WindowState.Normal;await Inspect(current,language+"-restored");Check(Math.Abs(current.ActualWidth-1120)<1&&Math.Abs(current.ActualHeight-780)<1,"maximized to normal restores original window size");current.CleanForSmoke();current.Close();current=null;}
 }catch(Exception ex){error=ex;Environment.ExitCode=1;}finally{if(current!=null){current.CleanForSmoke();current.Close();}UiText.SettingsPath=oldPath;UiText.RestoreSelection(oldLanguage);File.WriteAllText(Path.Combine(folder,"validation.json"),JsonSerializer.Serialize(new{passed=error==null,checks,reports,error=error?.ToString(),gameTested=false,physicalMouseTested=false},SongProject.Json));app.Shutdown(error==null?0:1);}};app.Run();
 }
}
